/**
 * catalog.js — read access to the generated catalog (data/products.json).
 * Single source at runtime; authored in data/catalog/**, generated by
 * scripts/build-catalog.js (see docs/ARCHITECTURE.md).
 */
import productsData from '../../data/products.json';

export const catalog = productsData;
export const products = productsData.products;
export const categories = productsData.categories;

export function visibleProducts(gender) {
  return products.filter((p) => p.visible && (!gender || p.gender === gender));
}

export function newArrivals(gender) {
  return visibleProducts(gender).filter((p) => p.badge === 'NEW');
}

export function categoryProducts(gender, category) {
  if (category === 'new-in') return newArrivals(gender);
  return visibleProducts(gender).filter((p) => p.category === category);
}

export function productBySlug(slug) {
  return products.find((p) => p.slug === slug && p.visible);
}

export function wearItWith(product) {
  // Complementary pieces: other gender-picks that pair well (different category first).
  return visibleProducts()
    .filter((p) => p.id !== product.id)
    .sort((a, b) => {
      const aScore = a.gender === product.gender ? 0 : 1;
      const bScore = b.gender === product.gender ? 0 : 1;
      return aScore - bScore;
    })
    .slice(0, 4);
}

export function subcategoryLabel(gender, category, key) {
  const cat = (categories[gender] || []).find((c) => c.category === category);
  return cat?.subcategories?.find((s) => s.key === key)?.label || '';
}

export function categoryLabel(gender, category) {
  if (category === 'new-in') return 'New In';
  return (categories[gender] || []).find((c) => c.category === category)?.label || category;
}

export const formatPrice = (pkr) => `PKR ${Number(pkr).toLocaleString('en-PK')}`;
